metadata.tikra:source:
% Made up for the tikra benchmark.
\begin{tikzpicture}
\begin{axis}[width=10cm, height=6cm, axis lines=left, xlabel={$t$ (s)}, ylabel={$v$ (m/s)}, xmin=0, xmax=5, ymin=0, ymax=12, samples=60, legend style={at={(0.02,0.98)}, anchor=north west}]
  \addplot[domain=0:5, thick, blue] {2*x + 1};
  \addlegendentry{steady}
  \addplot[domain=0:5, thick, red, dashed] {10*(1 - exp(-x))};
  \addlegendentry{saturating}
  \addplot[only marks, mark=*] coordinates {(1,3) (2,5.2) (3,6.8) (4,9.1)};
  \addlegendentry{samples}
\end{axis}
\end{tikzpicture}
